-- Replace hand-authored stint-0 gma_pattern pilot (item 6 was internally inconsistent —
-- see 2026-08-01 session) with a code-generated, code-verified set built on the
-- Carpenter, Just & Shell (1990) rule taxonomy. Every given cell in every item is
-- re-derived from its declared rule and asserted to match before insertion; answer
-- keys are computed from the same rule functions, never hand-picked.
-- Tier 1 (items 1-2): single perceptual rule (progression).
-- Tier 2 (items 3-5): single conceptual rule (distribution-of-three, row-shuffled).
-- Tier 3 (items 6-8): two rules stacked simultaneously, including one addition rule (item 8).

DELETE FROM public.hiregauge_instrument_items
WHERE cognitive_domain = 'gma_pattern' AND stint = 0 AND is_active = false;

INSERT INTO public.hiregauge_instrument_items (item_number, item_text, choices, answer_key, notes, stint, is_active, cognitive_domain, section) VALUES
(1, 'Shape steps circle→square→triangle left to right; same order in every row.', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "hexagon", "rotation": 0}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}}}'::jsonb, 'F', 'pattern_1_tier1_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(2, 'Triangle rotates 0°→90°→180° left to right; same order in every row.', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 270}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, "C": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 180}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 180}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}}}'::jsonb, 'F', 'pattern_2_tier1_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(3, 'Every row contains circle, square, and triangle exactly once — order re-shuffled each row (elimination, not sequence).', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "hexagon", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_3_tier2_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(4, 'Every row contains outline, solid, and striped fill exactly once — order re-shuffled each row.', '{"grid": [{"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "B": {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "circle", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}}}'::jsonb, 'F', 'pattern_4_tier2_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(5, 'Every row contains small, medium, and large exactly once — order re-shuffled each row.', '{"grid": [{"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, "B": {"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_5_tier2_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(6, 'Two rules at once: shape is circle/square/triangle once per row (elimination, reshuffled) AND rotation steps 0°→90°→180° by column.', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 90}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 90}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 180}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "hexagon", "rotation": 180}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 180}}}'::jsonb, 'F', 'pattern_6_tier3_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(7, 'Two rules at once: size is small/medium/large once per row (elimination, reshuffled) AND fill is constant within a row, changing outline→solid→striped row to row.', '{"grid": [{"fill": "outline", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "B": {"fill": "striped", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "striped", "size": "m", "count": 2, "shape": "circle", "rotation": 0}, "D": {"fill": "striped", "size": "m", "count": 1, "shape": "square", "rotation": 0}, "E": {"fill": "outline", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, "F": {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}}}'::jsonb, 'F', 'pattern_7_tier3_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(8, 'Two rules at once: shape is circle/square/triangle once per row (elimination, reshuffled) AND the third column''s count equals the sum of the first two columns'' counts.', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 3, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 3, "shape": "triangle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 4, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 3, "shape": "circle", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 3, "shape": "hexagon", "rotation": 0}, "F": {"fill": "solid", "size": "m", "count": 3, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_8_tier3_v2', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma');
